def db_connect() -> sqlite3.Connection:
    connection = sqlite3.connect(DATABASE_PATH)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA journal_mode=WAL")
    connection.execute("PRAGMA foreign_keys=ON")
    return connection


def initialize_database() -> None:
    with db_connect() as connection:
        connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS balances (
                user_id INTEGER PRIMARY KEY,
                coins INTEGER NOT NULL DEFAULT 0 CHECK(coins >= 0),
                diamonds INTEGER NOT NULL DEFAULT 0 CHECK(diamonds >= 0)
            );

            CREATE TABLE IF NOT EXISTS transactions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                amount INTEGER NOT NULL,
                currency TEXT NOT NULL CHECK(currency IN ('coins', 'diamonds')),
                description TEXT NOT NULL,
                created_at TEXT NOT NULL
            );

            CREATE INDEX IF NOT EXISTS idx_transactions_user
            ON transactions(user_id, id DESC);

            CREATE TABLE IF NOT EXISTS timely_cooldowns (
                user_id INTEGER PRIMARY KEY,
                last_claim_at TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS message_counts (
                guild_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                count INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (guild_id, user_id)
            );

            CREATE TABLE IF NOT EXISTS app_metadata (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS hidden_roles (
                guild_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                role_id INTEGER NOT NULL,
                hidden_at TEXT NOT NULL,
                PRIMARY KEY (guild_id, user_id, role_id)
            );

            CREATE TABLE IF NOT EXISTS antichrash_members (
                guild_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                saved_role_ids TEXT NOT NULL,
                activated_at TEXT NOT NULL,
                PRIMARY KEY (guild_id, user_id)
            );

            CREATE TABLE IF NOT EXISTS voice_stats (
                guild_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                total_seconds INTEGER NOT NULL DEFAULT 0,
                session_started_at TEXT,
                PRIMARY KEY (guild_id, user_id)
            );

            CREATE TABLE IF NOT EXISTS marriages (
                guild_id INTEGER NOT NULL,
                user1_id INTEGER NOT NULL,
                user2_id INTEGER NOT NULL,
                created_at TEXT NOT NULL,
                UNIQUE (guild_id, user1_id),
                UNIQUE (guild_id, user2_id)
            );
            """
        )
        connection.execute(
            """
            INSERT OR IGNORE INTO app_metadata(key, value)
            VALUES ('message_counts_last_reset', ?)
            """,
            (datetime.now(timezone.utc).isoformat(),),
        )


async def reset_message_counts_if_due() -> bool:
    """Сбрасывает текстовый топ один раз через каждые 30 суток."""
    now = datetime.now(timezone.utc)

    async with db_lock:
        with db_connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute(
                "SELECT value FROM app_metadata WHERE key = 'message_counts_last_reset'"
            ).fetchone()

            if row is None:
                connection.execute(
                    """
                    INSERT INTO app_metadata(key, value)
                    VALUES ('message_counts_last_reset', ?)
                    """,
                    (now.isoformat(),),
                )
                connection.commit()
                return False

            try:
                last_reset = datetime.fromisoformat(row["value"])
                if last_reset.tzinfo is None:
                    last_reset = last_reset.replace(tzinfo=timezone.utc)
            except (TypeError, ValueError):
                last_reset = now
                connection.execute(
                    """
                    UPDATE app_metadata
                    SET value = ?
                    WHERE key = 'message_counts_last_reset'
                    """,
                    (now.isoformat(),),
                )
                connection.commit()
                return False

            if now - last_reset < timedelta(days=MESSAGE_TOP_RESET_DAYS):
                connection.commit()
                return False

            connection.execute("DELETE FROM message_counts")
            connection.execute(
                """
                UPDATE app_metadata
                SET value = ?
                WHERE key = 'message_counts_last_reset'
                """,
                (now.isoformat(),),
            )
            connection.commit()
            print("Текстовый топ автоматически сброшен после 30 дней.")
            return True


