    now = datetime.now(timezone.utc)
    async with db_lock:
        with db_connect() as connection:
            row = connection.execute(
                "SELECT last_claim_at FROM timely_cooldowns WHERE user_id = ?",
                (interaction.user.id,),
            ).fetchone()
    embed = discord.Embed(title="Временная награда", color=COLOR)
