@lru_cache(maxsize=1)
def _get_profile_template() -> Image.Image:
    raw = base64.b64decode(PROFILE_TEMPLATE_B64)
    image = Image.open(io.BytesIO(raw)).convert("RGBA")
    image.load()
    return image


@lru_cache(maxsize=1)
def _get_love_profile_template() -> Image.Image:
    raw = base64.b64decode(LOVE_PROFILE_TEMPLATE_B64)
    image = Image.open(io.BytesIO(raw)).convert("RGBA")
    image.load()
    return image


@lru_cache(maxsize=1)
def _find_profile_fonts() -> tuple[str | None, str | None]:
    """Возвращает DejaVu Sans с поддержкой кириллицы."""
    # Matplotlib устанавливается через requirements.txt и содержит DejaVu Sans.
    try:
        from matplotlib import font_manager

        regular = font_manager.findfont(
            font_manager.FontProperties(family="DejaVu Sans", weight="normal"),
            fallback_to_default=True,
        )
        bold = font_manager.findfont(
            font_manager.FontProperties(family="DejaVu Sans", weight="bold"),
            fallback_to_default=True,
        )
        if Path(regular).exists() and Path(bold).exists():
            return regular, bold
    except Exception:
        pass

    # Резервный поиск системных шрифтов.
    names = {
        "regular": ("DejaVuSans.ttf", "LiberationSans-Regular.ttf", "NotoSans-Regular.ttf"),
        "bold": ("DejaVuSans-Bold.ttf", "LiberationSans-Bold.ttf", "NotoSans-Bold.ttf"),
    }
    roots = (
        Path("/usr/share/fonts"),
        Path("/usr/local/share/fonts"),
        Path("/System/Library/Fonts"),
        Path("C:/Windows/Fonts"),
    )

    def find(candidates: tuple[str, ...]) -> str | None:
        lowered = {name.lower() for name in candidates}
        for root in roots:
            if not root.exists():
                continue
            try:
                for candidate in root.rglob("*.ttf"):
                    if candidate.name.lower() in lowered:
                        return str(candidate)
            except OSError:
                continue
        return None

    return find(names["regular"]), find(names["bold"])


@lru_cache(maxsize=96)
def _load_profile_font(
    size: int,
    *,
    bold: bool = False,
) -> ImageFont.FreeTypeFont | ImageFont.ImageFont:
    regular_path, bold_path = _find_profile_fonts()
    font_path = bold_path if bold else regular_path
    if font_path:
        try:
            return ImageFont.truetype(font_path, size=size)
        except OSError:
            pass

    # Команда не падает даже при проблеме со шрифтом.
    try:
        return ImageFont.load_default(size=size)
    except TypeError:
        return ImageFont.load_default()


def _fit_profile_text(draw, text: str, max_width: int, preferred_size: int, *, bold: bool = False, minimum_size: int = 18):
    for size in range(preferred_size, minimum_size - 1, -1):
        font = _load_profile_font(size, bold=bold)
        bbox = draw.textbbox((0, 0), text, font=font)
        if bbox[2] - bbox[0] <= max_width:
            return font
    return _load_profile_font(minimum_size, bold=bold)


def _draw_centered_text(draw, box, text: str, font, fill=(245, 245, 247, 255)) -> None:
    left, top, right, bottom = box
    bbox = draw.textbbox((0, 0), text, font=font)
    width = bbox[2] - bbox[0]
    height = bbox[3] - bbox[1]
    x = left + (right - left - width) / 2
    y = top + (bottom - top - height) / 2 - bbox[1]
    draw.text((x, y), text, font=font, fill=fill)


def _circle_avatar(avatar_bytes: bytes | None, size: int) -> Image.Image:
    if avatar_bytes:
        try:
            avatar = Image.open(io.BytesIO(avatar_bytes)).convert("RGBA")
        except (OSError, ValueError):
            avatar = Image.new("RGBA", (size, size), (78, 80, 86, 255))
    else:
        avatar = Image.new("RGBA", (size, size), (78, 80, 86, 255))
    avatar = ImageOps.fit(avatar, (size, size), method=Image.Resampling.LANCZOS)
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    avatar.putalpha(mask)
    return avatar


def _place_avatar_in_slot(
    image: Image.Image,
    avatar_bytes: bytes | None,
    *,
    center_x: int,
    center_y: int,
    avatar_size: int,
    slot_size: int,
    slot_fill: tuple[int, int, int, int],
) -> None:
    """Очищает старую аватарку и ставит новую строго по центру кольца шаблона."""
    slot_left = center_x - slot_size // 2
    slot_top = center_y - slot_size // 2

    slot = Image.new("RGBA", (slot_size, slot_size), (0, 0, 0, 0))
    slot_draw = ImageDraw.Draw(slot)
    slot_draw.ellipse(
        (0, 0, slot_size - 1, slot_size - 1),
        fill=slot_fill,
    )
    image.alpha_composite(slot, (slot_left, slot_top))

    avatar = _circle_avatar(avatar_bytes, avatar_size)
    avatar_left = center_x - avatar_size // 2
    avatar_top = center_y - avatar_size // 2
    image.alpha_composite(avatar, (avatar_left, avatar_top))


def _cover_value(
    image: Image.Image,
    box: tuple[int, int, int, int],
    fill: tuple[int, int, int, int],
) -> None:
    """Закрывает только демонстрационное значение, не затрагивая подписи и панели."""
    ImageDraw.Draw(image).rectangle(box, fill=fill)


def _figma_px(value: float) -> int:
    """Перевод координат макета Figma 1920x880 в экспорт 1536x704."""
    return round(value * 0.8)


def _draw_figma_text(
    draw: ImageDraw.ImageDraw,
    text: str,
    *,
    left: float,
    top: float,
    width: float,
    height: float,
    size: float,
    fill: tuple[int, int, int, int],
    bold: bool = False,
    horizontal: str = "left",
    minimum_size: int = 12,
) -> None:
    """Рисует текст по X/Y/W/H из Figma с корректной нижней привязкой."""
    x = _figma_px(left)
    y = _figma_px(top)
    w = max(1, _figma_px(width))
    h = max(1, _figma_px(height))
    preferred = max(minimum_size, _figma_px(size))
    font = _fit_profile_text(
        draw,
        text,
        w,
        preferred,
        bold=bold,
        minimum_size=minimum_size,
    )

    if horizontal == "right":
        draw.text((x + w, y + h), text, font=font, fill=fill, anchor="rb")
    elif horizontal == "center":
        draw.text((x + w / 2, y + h), text, font=font, fill=fill, anchor="mb")
    else:
        draw.text((x, y + h), text, font=font, fill=fill, anchor="lb")


def _paste_figma_avatar(
    image: Image.Image,
    avatar_bytes: bytes | None,
    *,
    left: float,
    top: float,
    size: float,
    inset: float = 0,
) -> None:
    """Ставит аватар строго в квадрат из Figma, сохраняя центр окружности."""
    x = _figma_px(left + inset)
    y = _figma_px(top + inset)
    side = _figma_px(size - inset * 2)
    avatar = _circle_avatar(avatar_bytes, side)
    image.alpha_composite(avatar, (x, y))


def _build_profile_image(
    avatar_bytes: bytes | None,
    username: str,
    rank: int,
    coins: int,
    message_count: int,
    voice_seconds: int,
    role_name: str,
) -> io.BytesIO:
    """Обычный профиль, собранный по точным координатам макета Figma 1920x880."""
    image = _get_profile_template().copy()
    draw = ImageDraw.Draw(image)

    white = (255, 255, 255, 255)
    muted = (255, 255, 255, 204)  # 80% как в Figma

    # Большая аватарка: Avatar 240x240, X=278, Y=177.
    # В макете поверх неё есть Ellipse с рамкой 15px, поэтому изображение
    # помещается внутрь рамки и остаётся точно по центру.
    _paste_figma_avatar(
        image,
        avatar_bytes,
        left=278,
        top=177,
        size=240,
        inset=15,
    )

    # Маленькие аватарки нижних карточек: 100x100.
    _paste_figma_avatar(image, avatar_bytes, left=760, top=631, size=100)
    _paste_figma_avatar(image, avatar_bytes, left=1320, top=631, size=100)

    voice_minutes = max(0, voice_seconds // 60)
    hours, minutes = divmod(voice_minutes, 60)
    voice_text = f"{hours}ч {minutes}м"
    online_card_text = f"Онлайн: {hours}ч"

    rank_text = f"{rank}+" if rank >= 1000 else str(rank)

    # Динамические числа. Все X/Y/W/H, размер и выравнивание взяты из Figma.
    _draw_figma_text(
        draw, rank_text,
        left=899, top=184, width=161, height=38, size=53,
        fill=white, bold=True, horizontal="right", minimum_size=26,
    )
    _draw_figma_text(
        draw, str(coins),
        left=1460, top=184, width=173, height=38, size=53,
        fill=white, bold=True, horizontal="right", minimum_size=26,
    )
    _draw_figma_text(
        draw, voice_text,
        left=855, top=411, width=250, height=44, size=61.03,
        fill=white, bold=True, horizontal="right", minimum_size=28,
    )
    _draw_figma_text(
        draw, str(message_count),
        left=1456, top=411, width=181, height=44, size=61.03,
        fill=white, bold=True, horizontal="right", minimum_size=28,
    )

    # Нижняя левая карточка.
    _draw_figma_text(
        draw, username,
        left=888, top=653, width=210, height=23, size=32,
        fill=white, bold=True, horizontal="left", minimum_size=18,
    )
    _draw_figma_text(
        draw, online_card_text,
        left=888, top=692, width=210, height=19, size=26,
        fill=muted, horizontal="left", minimum_size=15,
    )

    # Нижняя правая карточка.
    _draw_figma_text(
        draw, username,
        left=1455, top=653, width=210, height=23, size=32,
        fill=white, bold=True, horizontal="left", minimum_size=18,
    )
    _draw_figma_text(
        draw, role_name,
        left=1455, top=692, width=210, height=19, size=26,
        fill=muted, horizontal="left", minimum_size=15,
    )

    result = io.BytesIO()
    image.convert("RGB").save(
        result,
        format="JPEG",
        quality=100,
        subsampling=0,
        optimize=True,
    )
    result.seek(0)
    return result


def _build_love_profile_image(
    first_avatar_bytes: bytes | None,
    second_avatar_bytes: bytes | None,
    combined_coins: int,
    together_days: int,
    combined_voice_seconds: int,
    room_name: str,
) -> io.BytesIO:
    """Профиль пары с отдельной геометрией исходного макета."""
    image = _get_love_profile_template().copy()
    draw = ImageDraw.Draw(image)

    white = (255, 255, 255, 255)

    # Центры колец в экспортированном шаблоне: (448, 252) и (697, 252).
    # Аватар помещается внутрь кольца, не перекрывая его обводку.
    _place_avatar_in_slot(
        image,
        first_avatar_bytes,
        center_x=448,
        center_y=252,
        avatar_size=126,
        slot_size=126,
        slot_fill=(0, 0, 0, 0),
    )
    _place_avatar_in_slot(
        image,
        second_avatar_bytes,
        center_x=697,
        center_y=252,
        avatar_size=126,
        slot_size=126,
        slot_fill=(0, 0, 0, 0),
    )

    voice_hours = max(0, combined_voice_seconds // 3600)
    voice_text = f"{voice_hours}ч"

    days_word = (
        "день"
        if together_days % 10 == 1 and together_days % 100 != 11
        else "дня"
        if together_days % 10 in (2, 3, 4)
        and together_days % 100 not in (12, 13, 14)
        else "дней"
    )
    days_text = f"{together_days} {days_word}"

    # Значения центрируются внутри собственных карточек шаблона.
    for box, value, preferred, minimum in (
        ((980, 118, 1265, 195), str(combined_coins), 49, 30),
        ((950, 285, 1270, 380), days_text, 44, 27),
        ((445, 390, 700, 490), voice_text, 56, 32),
    ):
        font = _fit_profile_text(
            draw,
            value,
            box[2] - box[0] - 24,
            preferred,
            bold=True,
            minimum_size=minimum,
        )
        _draw_centered_text(draw, box, value, font, white)

    # Название комнаты по Figma: 388x38, X=1109, Y=626,
    # Commissioner Medium 53px, выравнивание вправо/вниз.
    # Координаты Figma этого слоя относятся к артборду пары со смещением X=290.
    room_local_left = 1109 - 290
    _draw_figma_text(
        draw,
        room_name,
        left=room_local_left,
        top=626,
        width=388,
        height=38,
        size=53,
        fill=white,
        bold=True,
        horizontal="right",
        minimum_size=22,
    )

    result = io.BytesIO()
    image.convert("RGB").save(
        result,
        format="JPEG",
        quality=100,
        subsampling=0,
        optimize=True,
    )
    result.seek(0)
    return result


async def _read_profile_avatar(member: discord.abc.User, size: int = 512) -> bytes | None:
    try:
        return await asyncio.wait_for(member.display_avatar.with_size(size).read(), timeout=10)
    except (asyncio.TimeoutError, discord.HTTPException, OSError):
        return None


class MarryProposalView(discord.ui.View):
    def __init__(
        self,
        proposer: discord.Member,
        recipient: discord.Member,
    ):
        super().__init__(timeout=300)
        self.proposer = proposer
        self.recipient = recipient
        self.message: discord.Message | None = None
        self.finished = False
        self.action_lock = asyncio.Lock()

    def _disable_buttons(self) -> None:
        for item in self.children:
            if isinstance(item, discord.ui.Button):
                item.disabled = True

    def _result_embed(self, description: str, *, title: str = "Заключение брака") -> discord.Embed:
        embed = discord.Embed(
            title=title,
            description=description,
            color=COLOR,
        )
        embed.set_thumbnail(url=avatar_url(self.proposer))
        return embed

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.recipient.id:
            await interaction.response.send_message(
                "Ответить на предложение может только пользователь, которому оно адресовано.",
                ephemeral=True,
            )
            return False
        return True

    @discord.ui.button(label="Принять", style=discord.ButtonStyle.secondary)
    async def accept(
        self,
        interaction: discord.Interaction,
        button: discord.ui.Button,
    ):
        async with self.action_lock:
            if self.finished:
                await interaction.response.send_message(
                    "На это предложение уже ответили.",
                    ephemeral=True,
                )
                return

            if interaction.guild is None:
                await interaction.response.send_message(
                    "Команда доступна только на сервере.",
                    ephemeral=True,
                )
                return

            created = await create_marriage(
                interaction.guild.id,
                self.proposer.id,
                self.recipient.id,
            )
            self.finished = True
            self._disable_buttons()

            if created:
                embed = self._result_embed(
                    f"{self.proposer.mention}, {self.recipient.mention} "
                    "**принял(а)** предложение о браке"
                )
            else:
                embed = self._result_embed(
                    f"{self.proposer.mention}, один из пользователей **уже** в браке",
                    title="Заключить брак",
                )

            await interaction.response.edit_message(embed=embed, view=None)
            self.stop()

    @discord.ui.button(label="Отказать", style=discord.ButtonStyle.danger)
    async def decline(
        self,
        interaction: discord.Interaction,
        button: discord.ui.Button,
    ):
        async with self.action_lock:
            if self.finished:
                await interaction.response.send_message(
                    "На это предложение уже ответили.",
                    ephemeral=True,
                )
                return

            self.finished = True
            self._disable_buttons()
            embed = self._result_embed(
                f"{self.proposer.mention}, {self.recipient.mention} "
                "**отказалась** от предложения о браке"
            )
            await interaction.response.edit_message(embed=embed, view=None)
            self.stop()

    async def on_timeout(self):
        async with self.action_lock:
            if self.finished:
                return

            self.finished = True
            self._disable_buttons()
            embed = self._result_embed(
                f"{self.proposer.mention}, время на ответ **вышло**",
                title="Заключить брак",
            )

            if self.message is not None:
                try:
                    await self.message.edit(embed=embed, view=None)
                except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                    pass


@bot.tree.command(name="marry", description="Сделать предложение пользователю")
@app_commands.describe(user="Пользователь, которому нужно сделать предложение")
@app_commands.rename(user="пользователь")
async def marry(interaction: discord.Interaction, user: discord.Member):
    if not interaction.guild or not isinstance(interaction.user, discord.Member):
        await interaction.response.send_message(
            "Команда доступна только на сервере.",
            ephemeral=True,
        )
        return

    proposer = interaction.user

    if user.id == proposer.id:
        embed = discord.Embed(
            title="Заключить брак",
            description=(
                f"{proposer.mention}, Вы **не можете** заключить "
                "**брак** сами с собой"
            ),
            color=COLOR,
        )
        embed.set_thumbnail(url=avatar_url(proposer))
        await interaction.response.send_message(embed=embed)
        return

    proposer_partner = await get_marriage_partner_id(interaction.guild.id, proposer.id)
    if proposer_partner is not None:
        embed = discord.Embed(
            title="Заключить брак",
            description=f"{proposer.mention}, Вы **уже** в браке",
            color=COLOR,
        )
        embed.set_thumbnail(url=avatar_url(proposer))
        await interaction.response.send_message(embed=embed)
        return

    recipient_partner = await get_marriage_partner_id(interaction.guild.id, user.id)
    if recipient_partner is not None:
        embed = discord.Embed(
            title="Заключить брака",
            description=f"{proposer.mention}, пользователь **уже** в браке",
            color=COLOR,
        )
        embed.set_thumbnail(url=avatar_url(proposer))
        await interaction.response.send_message(embed=embed)
        return

    embed = discord.Embed(
        title="Заключение брака",
        description=(
            f"{user.mention}, пользователь {proposer.mention} "
            "**сделал** вам предложение"
        ),
        color=COLOR,
    )
    embed.set_thumbnail(url=avatar_url(proposer))

    view = MarryProposalView(proposer, user)
    await interaction.response.send_message(embed=embed, view=view)
    view.message = await interaction.original_response()


