class ProfileMarriageView(discord.ui.View):
    def __init__(self, member: discord.Member, partner: discord.Member):
        super().__init__(timeout=120)
        self.member = member
        self.partner = partner

    @discord.ui.button(label="Любовный профиль", style=discord.ButtonStyle.secondary)
    async def love_profile(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.guild is None:
            await interaction.response.send_message("Команда доступна только на сервере.", ephemeral=True)
            return

        info = await get_marriage_info(interaction.guild.id, self.member.id)
        if info is None:
            await interaction.response.send_message("Вы больше не состоите в браке.", ephemeral=True)
            return

        partner_id, created_at = info
        partner = interaction.guild.get_member(partner_id)
        if partner is None:
            try:
                partner = await interaction.guild.fetch_member(partner_id)
            except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                await interaction.response.send_message("Не удалось найти партнёра на сервере.", ephemeral=True)
                return

        await interaction.response.defer(thinking=True)
        (member_coins, _), (partner_coins, _) = await asyncio.gather(
            get_balance(self.member.id),
            get_balance(partner.id),
        )
        member_stats, partner_stats = await asyncio.gather(
            get_profile_statistics(interaction.guild.id, self.member.id),
            get_profile_statistics(interaction.guild.id, partner.id),
        )
        avatars = await asyncio.gather(
            _read_profile_avatar(self.member),
            _read_profile_avatar(partner),
        )
        together_days = max(1, (datetime.now(timezone.utc) - created_at).days + 1)
        combined_voice = member_stats[2] + partner_stats[2]
        try:
            image = await asyncio.wait_for(
                asyncio.to_thread(
                    _build_love_profile_image,
                    avatars[0],
                    avatars[1],
                    member_coins + partner_coins,
                    together_days,
                    combined_voice,
                    "Любовный профиль",
                ),
                timeout=20,
            )
        except asyncio.TimeoutError:
            await interaction.followup.send(
                "Не удалось создать любовный профиль за 20 секунд. Попробуйте ещё раз.",
                ephemeral=True,
            )
            return
        file = discord.File(image, filename=f"love_profile_{self.member.id}_{partner.id}.jpg")
        await interaction.followup.send(file=file, view=LoveProfileResultView(self.member, partner))


@bot.tree.command(name="profile", description="Посмотреть профиль пользователя")
@app_commands.rename(user="пользователь")
async def profile(interaction: discord.Interaction, user: discord.Member | None = None):
    if not interaction.guild:
        await interaction.response.send_message("Команда доступна только на сервере.", ephemeral=True)
        return

    target = user or interaction.user
    await interaction.response.defer(thinking=True)

    try:
        (coins, _), statistics, marriage_info, avatar_bytes = await asyncio.gather(
            get_balance(target.id),
            get_profile_statistics(interaction.guild.id, target.id),
            get_marriage_info(interaction.guild.id, target.id),
            _read_profile_avatar(target),
        )
        message_count, rank, voice_seconds = statistics

        role_name = "Участник"
        if isinstance(target, discord.Member):
            visible_roles = [role for role in target.roles if not role.is_default() and not role.managed]
            if visible_roles:
                role_name = visible_roles[-1].name

        image = await asyncio.wait_for(
            asyncio.to_thread(
                _build_profile_image,
                avatar_bytes,
                target.display_name,
                rank,
                coins,
                message_count,
                voice_seconds,
                role_name,
            ),
            timeout=20,
        )
    except asyncio.TimeoutError:
        await interaction.followup.send("Не удалось создать профиль за 20 секунд. Попробуйте ещё раз.", ephemeral=True)
        return
    except Exception as error:
        print(f"Ошибка генерации профиля пользователя {target.id}: {error!r}")
        await interaction.followup.send("Не удалось создать профиль. Проверьте, что в requirements.txt есть matplotlib и Pillow.", ephemeral=True)
        return

    file = discord.File(image, filename=f"profile_{target.id}.jpg")
    if marriage_info is None:
        await interaction.followup.send(file=file)
        return

    partner_id, _ = marriage_info
    partner = interaction.guild.get_member(partner_id)
    if partner is None:
        try:
            partner = await interaction.guild.fetch_member(partner_id)
        except (discord.NotFound, discord.Forbidden, discord.HTTPException):
            partner = None

    if partner is None:
        await interaction.followup.send(file=file)
    else:
        await interaction.followup.send(file=file, view=ProfileMarriageView(target, partner))


